<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest\MessageAllowController;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest\MessageListController;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest\MessageCreateController;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest\MessageRetrieveController;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest\MessageUpdateController;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest\MessageDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Notification\Message\Application\Service\Visibility\MessageRestrictFilterToVisibility;
use Civi\Lughauth\Features\Notification\Message\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Notification\Message\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Notification\Message\Application\Service\Visibility\MessageCollectNonEditableFields;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Driven\MessageReadRepositoryAdapter;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Driven\MessageWriteRepositoryAdapter;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageReadGateway;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageWriteGateway;

class MessagePlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[MessageReadGateway::class] = \DI\autowire(MessageReadRepositoryAdapter::class);
        $def[MessageWriteGateway::class] = \DI\autowire(MessageWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/template/template', [$this, 'setRoutesForMessage']);
        $collector->group('/api/me/acl/template/template', [$this, 'setRoutesForMessageAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(MessageRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(MessageCollectNonEditableFields::class, FixTenantExcludingRoot::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("message", "list", "READ");
            $handler->registerResourceAction("message", "create", "WRITE");
            $handler->registerResourceAction("message", "retrieve", "READ");
            $handler->registerResourceAction("message", "update", "WRITE");
            $handler->registerResourceAction("message", "delete", "WRITE");

            $handler->registerResourceAttribute("message", "target", "MANAGE");
            $handler->registerResourceAttribute("message", "tenant", "MANAGE");
            $handler->registerResourceAttribute("message", "urgent", "MANAGE");
            $handler->registerResourceAttribute("message", "content", "MANAGE");
            $handler->registerResourceAttribute("message", "retries", "MANAGE");
            $handler->registerResourceAttribute("message", "createdAt", "MANAGE");
            $handler->registerResourceAttribute("message", "sendAt", "MANAGE");
            $handler->registerResourceAttribute("message", "lockAt", "MANAGE");
            $handler->registerResourceAttribute("message", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForMessageAcl(RouteCollectorProxy $messageGroup): void
    {
        $messageGroup->get('', [MessageAllowController::class, 'genericAllow']);
        $messageGroup->get('/{uid}', [MessageAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForMessage(RouteCollectorProxy $messageGroup): void
    {
        $messageGroup->get('', [MessageListController::class, 'list']);
        $messageGroup->post('', [MessageCreateController::class, 'create']);
        $messageGroup->get('/{uid}', [MessageRetrieveController::class, 'retrieve']);
        $messageGroup->put('/{uid}', [MessageUpdateController::class, 'update']);
        $messageGroup->delete('/{uid}', [MessageDeleteController::class, 'delete']);
        $messageGroup->delete('', [MessageDeleteController::class, 'deleteAllForQuery']);
        $messageGroup->get('/~/delete-status/{uid}', [MessageDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
